function indexTwice(nums: number[]): number[] {
  const n = nums.length;
  for (let i = 0; i < n; i++) nums[i] += n * (nums[nums[i] % n] % n);
  for (let i = 0; i < n; i++) nums[i] = Math.floor(nums[i] / n);
  return nums;
}

